def patch_player_physics(bcdir, game_sigs=None):
    """The player physics functions (PLAYERFN*_SIG, or game_sigs {n: signature}) -> PS1PlayerFn<N> / return, all or
    none: PS1PlayerFn6 calls PS1PlayerFn51 directly, so every signature is checked before any function is rewritten."""
    names, vars_ = bs.tables(3)
    fn = [n for n, _ in names]
    ret = fn.index('return')
    path = os.path.join(bcdir, 'GlobalCode.bin')
    raw = open(path, 'rb').read()
    code, p = bs.blocks(raw, 0)
    rest = raw[p:]
    starts = [s for s, _ in bs.load(path)[4]]
    sigs = [(n, (game_sigs or {}).get(n) or globals()['PLAYERFN%d_SIG' % n]) for n in (2, 3, 4, 5, 6, 51, 52, 53)]
    found, already = [], 0
    for n, sig in sigs:
        op = fn.index('PS1PlayerFn%d' % n)
        hits = []
        for f, s in enumerate(starts):
            if not 0 <= s < len(code):
                continue
            if code[s] == op:
                already += 1
                hits = None
                break
            try:
                if listing(instructions(code, s, names, vars_)) == sig:
                    hits.append((f, s))
            except (IndexError, KeyError):
                continue
        if hits is None:
            continue
        if len(hits) != 1:
            sys.exit('ERROR patch_bytecode: expected one GlobalCode function for PS1PlayerFn%d, found %d' % (n, len(hits)))
        found.append((n, op, hits[0]))
    if already == len(sigs):
        return 'player physics already native'
    if already:
        sys.exit('ERROR patch_bytecode: player physics partly native')
    for n, op, (f, s) in found:
        code[s:s + 2] = [op, ret]
    open(path, 'wb').write(encode(code) + rest)
    assert bs.blocks(open(path, 'rb').read(), 0)[0] == code
    return 'player physics native: functions %s' % ' '.join(str(f) for _, _, (f, _) in found)


